def count_coprime(n, m):
    if n <= 0:
        return 0
    if m == 1:
        return n

    # Distinct prime factors of m via trial division
    factors = []
    mm = m
    d = 2
    while d * d <= mm:
        if mm % d == 0:
            factors.append(d)
            while mm % d == 0:
                mm //= d
        d += 1
    if mm > 1:
        factors.append(mm)

    # Inclusion-exclusion: count numbers in [1, n] sharing a prime factor with m
    k = len(factors)
    divisible = 0
    for mask in range(1, 1 << k):
        prod = 1
        bits = 0
        for i in range(k):
            if mask & (1 << i):
                prod *= factors[i]
                bits += 1
        term = n // prod
        if bits % 2 == 1:
            divisible += term
        else:
            divisible -= term

    return n - divisible
