def count_coprime(n, m):
    """Count integers in [1, n] that are coprime to m, via inclusion-exclusion
    over the distinct prime factors of m."""
    if n <= 0:
        return 0
    if m == 1:
        return n

    # Distinct prime factors of m (trial division; inputs kept small)
    primes = []
    temp = m
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            primes.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        primes.append(temp)

    # Inclusion-exclusion: |A1 ∪ ... ∪ Ak| subtracted from n
    total = 0
    k = len(primes)
    for mask in range(1 << k):
        prod = 1
        bits = 0
        for i in range(k):
            if mask & (1 << i):
                prod *= primes[i]
                bits += 1
        if bits % 2 == 0:
            total += n // prod
        else:
            total -= n // prod
    return total
