def tsp_length(dist):
    n = len(dist)
    if n <= 1:
        return 0

    full = (1 << n) - 1
    INF = float('inf')

    # dp[mask][i] = minimum cost of a path that starts at city 0,
    # visits exactly the cities in `mask`, and ends at city i.
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0

    for mask in range(1, 1 << n):
        if not (mask & 1):
            continue  # every valid path includes the start city 0
        row = dp[mask]
        for i in range(n):
            cur = row[i]
            if cur == INF:
                continue
            di = dist[i]
            for j in range(n):
                if mask & (1 << j):
                    continue
                nmask = mask | (1 << j)
                val = cur + di[j]
                if val < dp[nmask][j]:
                    dp[nmask][j] = val

    return min(dp[full][i] + dist[i][0] for i in range(n))
