import heapq

def min_effort(heights):
    rows = len(heights)
    cols = len(heights[0])
    if rows == 1 and cols == 1:
        return 0

    INF = float('inf')
    effort = [[INF] * cols for _ in range(rows)]
    effort[0][0] = 0
    heap = [(0, 0, 0)]  # (current max effort, row, col)

    while heap:
        e, r, c = heapq.heappop(heap)
        if r == rows - 1 and c == cols - 1:
            return e
        if e > effort[r][c]:
            continue
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                ne = max(e, abs(heights[r][c] - heights[nr][nc]))
                if ne < effort[nr][nc]:
                    effort[nr][nc] = ne
                    heapq.heappush(heap, (ne, nr, nc))

    return effort[rows - 1][cols - 1]
```

